WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY method, status ORDER BY paid_at NULLS FIRST, id) AS latest_rank FROM payments QUALIFY latest_rank = 1) SELECT id, order_id, method, amount, status, latest_rank, CASE WHEN status RLIKE '^(SUCCESS|FAILED)$' THEN 'PRIORITY' WHEN status RLIKE '^(REFUNDED)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS status_zone FROM latest ORDER BY id DESC NULLS FIRST, order_id;
